// Some portions generated by Claude
import { graphNodeSize } from "./graph-geometry.ts";
import { LAYOUT_SPACING as gap } from "./graph-layout-spacing.ts";
import { SpatialGrid } from "./spatial-grid.ts";
import type { Graph, PointerPosition } from "./graph-types.ts";

type Arrange = (subgraph: Graph) => Map<string, PointerPosition> | Promise<Map<string, PointerPosition>>;

/** The middle of the points' extent. */
function middle(points: Iterable<PointerPosition>) {
  let minX = Infinity, maxX = -Infinity, minY = Infinity, maxY = -Infinity;
  for (const { x, y } of points) {
    minX = Math.min(minX, x);
    maxX = Math.max(maxX, x);
    minY = Math.min(minY, y);
    maxY = Math.max(maxY, y);
  }
  return { x: (minX + maxX) / 2, y: (minY + maxY) / 2, width: maxX - minX, height: maxY - minY };
}

/**
 * Lays out part of the graph as one block. `arrange` places the subgraph of the unpinned nodes in `ids` (with the
 * links among them); the block is centred where those nodes stand now and, when it would cover a node outside it, moved
 * whole to the nearest free place within about its own size, so its shape (a grid, ranks) stays intact. Every other
 * node keeps its position.
 */
export async function layoutSubset(graph: Graph, ids: ReadonlySet<string>, arrange: Arrange) {
  const positions = new Map(graph.nodes.map((node) => [node.id, { x: node.x ?? 0, y: node.y ?? 0 }]));
  const members = graph.nodes.filter((node) => ids.has(node.id) && !node.pinned);
  if (!members.length) return positions;
  const memberIds = new Set(members.map((node) => node.id));
  const arranged = await arrange({
    nodes: members,
    edges: graph.edges.filter((edge) => memberIds.has(edge.source) && memberIds.has(edge.target)),
    revision: graph.revision,
  });
  const block = members.map((node) => {
    const size = graphNodeSize(node);
    return { id: node.id, ...(arranged.get(node.id) ?? positions.get(node.id)!), width: size.width, height: size.height };
  });
  const from = middle(members.map((node) => positions.get(node.id)!));
  const to = middle(block);
  const offset = clearOffset(
    block,
    graph.nodes.filter((node) => !memberIds.has(node.id)),
    { x: from.x - to.x, y: from.y - to.y },
    Math.max(400, to.width, to.height),
  );
  for (const node of block) positions.set(node.id, { x: node.x + offset.x, y: node.y + offset.y });
  return positions;
}

/**
 * The offset nearest `wanted` (rings of growing radius, up to `reach`) at which no block card comes within the layout
 * gaps of a card outside the block; `wanted` itself when none is free.
 */
function clearOffset(
  block: { x: number; y: number; width: number; height: number }[],
  others: Graph["nodes"],
  wanted: PointerPosition,
  reach: number,
) {
  if (!others.length) return wanted;
  const grid = new SpatialGrid(256);
  for (const node of others) {
    const size = graphNodeSize(node), x = node.x ?? 0, y = node.y ?? 0;
    grid.insert({ minX: x - size.width / 2, maxX: x + size.width / 2, minY: y - size.height / 2, maxY: y + size.height / 2 });
  }
  const found: number[] = [];
  const free = (dx: number, dy: number) =>
    block.every((card) => {
      const halfWidth = card.width / 2 + gap.nodeGapX / 2, halfHeight = card.height / 2 + gap.nodeGapY / 2;
      const x = card.x + dx, y = card.y + dy;
      return grid.search(x - halfWidth, y - halfHeight, x + halfWidth, y + halfHeight, found).length === 0;
    });
  if (free(wanted.x, wanted.y)) return wanted;
  const step = Math.max(gap.nodeGapX, reach / 24);
  for (let radius = step; radius <= reach; radius += step) {
    const directions = Math.max(8, Math.ceil((2 * Math.PI * radius) / step));
    for (let i = 0; i < directions; i++) {
      const angle = (2 * Math.PI * i) / directions;
      const dx = wanted.x + radius * Math.cos(angle), dy = wanted.y + radius * Math.sin(angle);
      if (free(dx, dy)) return { x: dx, y: dy };
    }
  }
  return wanted;
}
